let editingLibraryId=null;
function openLibraryEditor(id=null){editingLibraryId=id;const library=archive.libraries.find(l=>l.id===id),form=$('#libraryForm');form.reset();form.elements.name.value=library?.name||'';form.elements.background.value=library?.background||'#0a0a0a';form.elements.line.value=library?.line||'#77776c';$('#libraryEditorTitle').textContent=library?'Edit Library':'Create Library';$('#libraryEditor').showModal();form.elements.name.focus()}
