$('#libraryForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,name=form.elements.name.value.trim();if(!name)return;const submit=form.querySelector('[type=submit]');submit.disabled=true;try{const id=editingLibraryId||crypto.randomUUID(),existing=archive.libraries.find(l=>l.id===id),library={...existing,id,name,background:form.elements.background.value,line:form.elements.line.value,order:existing?.order??archive.libraries.length,archived:existing?.archived??false};await saveArchive({...archive,books,libraries:existing?archive.libraries.map(l=>l.id===id?library:l):[...archive.libraries,library]});currentLibraryId=id;await setting('activeLibrary',id);render();$('#libraryEditor').close();message(existing?'Library saved.':'Library created.')}catch(e){serious(e)}finally{submit.disabled=false}};
let archive={books:[],libraries:[],fonts:[],settings:[]},currentLibraryId=null,creationDraft=null,dragBookId=null,dragLibraryId=null,designDraft=null;
const objectURLs=new Map();
function assetURL(blob){if(!(blob instanceof Blob))return '';if(!objectURLs.has(blob))objectURLs.set(blob,URL.createObjectURL(blob));return objectURLs.get(blob)}
async function validateImage(file){if(!/^image\/(png|jpeg|webp)$/.test(file.type)||file.size>10*1024*1024)throw new Error('Choose a PNG, JPG or WebP under 10 MB.');const image=await createImageBitmap(file);image.close();}
function serious(error){message(error.message||String(error),true);const dialog=$('#errorDialog');$('#errorText').textContent=error.message||String(error);if(!dialog.open)dialog.showModal()}
function activeBooks(id=currentLibraryId){return books.filter(b=>!b.deletedAt&&b.libraryId===id).sort((a,b)=>(a.order||0)-(b.order||0))}
function activeLibraries(){return archive.libraries.filter(l=>!l.archived).sort((a,b)=>a.order-b.order)}
async function reloadArchive(){archive=await ArchiveDB.read(db);books=archive.books;await loadFonts()}
async function saveArchive(next,replace=false){const baseline={...archive,books};if(replace){await ArchiveDB.write(db,next);archive=next}else archive=await ArchiveDB.patch(db,next,baseline);books=archive.books;render()}
async function setting(id,value){await new Promise((resolve,reject)=>{const tx=db.transaction('settings','readwrite');tx.objectStore('settings').put({id,value});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});archive.settings=archive.settings.filter(s=>s.id!==id).concat({id,value})}
function getSetting(id,fallback){return archive.settings.find(s=>s.id===id)?.value??fallback}
function ensureCapacity(id=currentLibraryId){archive.books=books;if(!ArchiveModel.canAdd(archive,id))throw new Error('This Library is full (16/16) or archived. Select or create another Library first.');}
const originalPersist=persist;
persist=async function(book){if(!books.some(b=>b.id===book.id)){ensureCapacity(book.libraryId||currentLibraryId);book.libraryId=book.libraryId||currentLibraryId;book.order=Date.now()}await originalPersist(book)};
// Keep transaction-based updates from app.js and mirror the archive's in-memory books.
const originalUpdate=updateBook;updateBook=async function(id,change){const b=await originalUpdate(id,change);archive.books=books;return b};
const originalBookMarkup=bookMarkup;
bookMarkup=function(b,index,preview=false){const html=originalBookMarkup(b,index,preview);if(preview)return html;return html.replace('data-id=',`draggable="true" data-id=`).replace(' title="',` title="${escapeHTML((b.finished?'Finished':b.readerPosition?'Reading':'Not started')+' · '+Math.round((b.readerPosition?.progress||0)*100)+'% · '+(b.readerPosition?.chapter||'No chapter yet'))} — `)};
shelfMarkup=function(row){row=ArchiveModel.autoStack(row);let html='',used=new Set();for(const b of row){if(used.has(b.id))continue;const group=b.stackId&&ArchiveModel.horizontal(b)?ArchiveModel.stackMembers(row,b):[b];group.forEach(x=>used.add(x.id));html+=group.length>1?'<div class="book-stack" data-stack="'+escapeHTML(b.stackId)+'">'+group.map(x=>bookMarkup(x,row.indexOf(x))).join('')+'</div>':bookMarkup(b,row.indexOf(b));}return html};
function stackDropIntent(event,source,target){
  if(!source||!target||source.id===target.id||!ArchiveModel.horizontal(source)||!ArchiveModel.horizontal(target))return false;
  const rect=event.currentTarget.getBoundingClientRect(),x=(event.clientX-rect.left)/rect.width;
  return !event.altKey&&(event.shiftKey||(x>.22&&x<.78));
}

pages=function(){return [activeBooks()]};
render=function(){persistAutomaticStacks();const libs=activeLibraries();if(!libs.some(l=>l.id===currentLibraryId))currentLibraryId=libs[0]?.id||null;const lib=archive.libraries.find(l=>l.id===currentLibraryId),row=activeBooks();
  $('#libraryTabs').innerHTML=libs.map(l=>`<button draggable="true" data-library="${escapeHTML(l.id)}" aria-current="${l.id===currentLibraryId?'page':'false'}" class="${l.id===currentLibraryId?'active':''}">${escapeHTML(l.name)}</button><button class="library-context-button" data-library-menu="${escapeHTML(l.id)}" aria-label="Manage ${escapeHTML(l.name)}">⋯</button>`).join('')+'<button id="newLibrary" aria-label="Create Library">+</button><button id="manageLibraries" aria-label="Manage Libraries including archived">⋯</button>';
  $('#library').style.background=lib?.background||'#0a0a0a';$('#books').style.borderColor=lib?.line||'#77776c';$('#books').className='books'+(view==='list'?' list':'');$('#books').innerHTML='<div id="shelfComposition">'+(view==='list'?row.map(b=>bookMarkup(b,row.indexOf(b))).join(''):shelfMarkup(row))+'</div>';
  $('#count').textContent=row.length+'/16';$('#shelfLabel').textContent='';$('#libraryEmpty').hidden=row.length>0;$('#libraryEmpty').textContent=lib?'No books yet. Use + to add a book.':'Create a Library with + to begin.';$('#shelfCaption').textContent='Click to read · Right-click a book for actions';$('#previous').hidden=true;$('#next').hidden=true;$('#pageCount').textContent='';$('#spineView').classList.toggle('active',view==='shelf');$('#listView').classList.toggle('active',view==='list');
  document.querySelectorAll('header .create-book,header .import').forEach(el=>el.disabled=!lib||row.length>=16);$('#bookCapacityHint').hidden=!!lib&&row.length<16;
  $('#newLibrary').onclick=()=>openLibraryEditor();
  $('#libraryTabs').querySelectorAll('[data-library-menu]').forEach(el=>el.onclick=()=>openLibraryContext(el.dataset.libraryMenu));
  $('#manageLibraries').onclick=()=>openSettings('libraries');
  $('#libraryTabs').querySelectorAll('[data-library]').forEach(el=>{el.onclick=async()=>{currentLibraryId=el.dataset.library;render();try{await setting('activeLibrary',currentLibraryId)}catch(e){serious(e)}};el.ondragstart=e=>{if(e.target===el){dragLibraryId=el.dataset.library;dragBookId=null;e.dataTransfer.setData('text/plain',dragLibraryId)}};el.ondragover=e=>{e.preventDefault();el.classList.add('drop-target')};el.ondragleave=()=>el.classList.remove('drop-target');el.ondrop=async e=>{e.preventDefault();el.classList.remove('drop-target');try{if(dragBookId){if(books.find(b=>b.id===dragBookId)?.libraryId!==el.dataset.library)await saveArchive(ArchiveModel.move({...archive,books},dragBookId,el.dataset.library))}else if(dragLibraryId){const reordered=[...libs],from=reordered.findIndex(l=>l.id===dragLibraryId),to=reordered.findIndex(l=>l.id===el.dataset.library);reordered.splice(to,0,reordered.splice(from,1)[0]);await saveArchive({...archive,books,libraries:archive.libraries.map(l=>({...l,order:reordered.findIndex(x=>x.id===l.id)>=0?reordered.findIndex(x=>x.id===l.id):l.order}))})}}catch(e){serious(e)}dragBookId=null;dragLibraryId=null}});
  $('#books').querySelectorAll('[data-id]').forEach(el=>{el.ondragstart=e=>{dragBookId=el.dataset.id;dragLibraryId=null;e.dataTransfer.setData('text/plain',dragBookId)};el.ondragover=e=>{e.preventDefault();const stack=stackDropIntent(e,books.find(b=>b.id===dragBookId),books.find(b=>b.id===el.dataset.id));el.classList.toggle('stack-target',stack);el.classList.toggle('drop-target',!stack);el.dataset.dropHint=stack?'Stack here (max 3)':e.altKey?'Move entire stack':'Reorder beside (separate book)';$('#shelfCaption').textContent=el.dataset.dropHint;e.dataTransfer.dropEffect='move'};el.ondragend=()=>{dragBookId=null;$('#shelfCaption').textContent='Click to read · Right-click a book for actions';$('#books').querySelectorAll('.stack-target,.drop-target').forEach(n=>n.classList.remove('stack-target','drop-target'))};el.ondragleave=()=>el.classList.remove('stack-target','drop-target');el.ondrop=async e=>{e.preventDefault();const id=dragBookId,target=el.dataset.id;if(!id||id===target)return;try{if(stackDropIntent(e,books.find(b=>b.id===id),books.find(b=>b.id===target))){const rect=el.getBoundingClientRect(),above=e.clientY<rect.top+rect.height/2;await saveArchive({...archive,books:ArchiveModel.stackBooks(books,id,target,above)})}else{const source=books.find(b=>b.id===id),moving=e.altKey&&source.stackId?ArchiveModel.stackMembers(books,source).map(b=>b.id):[id];
if(moving.includes(target))return;const ids=row.map(b=>b.id).filter(id=>!moving.includes(id)),to=ids.indexOf(target);ids.splice(Math.max(0,to),0,...moving);
await saveArchive({...archive,books:books.map(x=>ids.includes(x.id)?{...x,order:ids.indexOf(x.id),...(moving.includes(x.id)&&e.altKey&&moving.length>1?{stackMode:'manual'}:x.id===id&&!e.altKey?{stackId:null,stackOrder:null,stackMode:'separate'}:{})}:x)})}}catch(e){serious(e)}finally{dragBookId=null;render()}};el.oncontextmenu=e=>{e.preventDefault();manageBook(el.dataset.id)};const preview=()=>{const b=books.find(b=>b.id===el.dataset.id),rect=el.getBoundingClientRect(),tip=$('#bookPreview');tip.innerHTML='<strong>'+escapeHTML(b.title)+'</strong><p>'+escapeHTML(b.author)+'</p><p>'+(b.finished?'Finished':b.readerPosition?'Reading':'Not started')+' · '+Math.round((b.readerPosition?.progress||0)*100)+'%</p><p>'+escapeHTML(b.readerPosition?.chapter||'No chapter yet')+'</p>';tip.style.left=Math.max(8,Math.min(innerWidth-260,rect.left))+'px';tip.style.top=Math.max(8,rect.top-140)+'px';tip.hidden=false};el.onpointerenter=preview;el.onpointerleave=()=>$('#bookPreview').hidden=true;el.onfocus=preview;el.onblur=()=>$('#bookPreview').hidden=true});
  scaleShelf();requestAnimationFrame(scaleShelf);
};
let autoStackSaving=false,autoStackFailure=false;
async function persistAutomaticStacks(){
  if(!db||autoStackSaving||autoStackFailure)return;
  const baseline={...archive,books},normalized=ArchiveModel.autoStack(books);
  if(normalized.every((b,i)=>b===books[i]))return;
  autoStackSaving=true;
  try{await ArchiveDB.patch(db,{...archive,books:normalized},baseline);await reloadArchive();autoStackSaving=false;render()}
  catch(e){autoStackSaving=false;autoStackFailure=true;serious(e)}
}
function scaleShelf(){const composition=$('#shelfComposition');if(!composition)return;if(view==='list'){composition.style.transform='';$('#books').style.height='auto';return}composition.style.transform='none';const width=composition.scrollWidth,height=composition.scrollHeight,scale=Math.min(1,Math.max(1,$('#books').clientWidth-12)/Math.max(1,width));composition.style.transform=`scale(${scale})`;$('#books').style.height=Math.max(200,height*scale+32)+'px'}
window.addEventListener('resize',()=>{scaleShelf();if(Board.bookId)Board.refresh()});
function manageBook(id){const b=books.find(b=>b.id===id);$('#bookMenuBody').innerHTML=`<h2>${escapeHTML(b.title)}</h2><p>${b.finished?'Finished':b.readerPosition?'Reading':'Not started'} · ${Math.round((b.readerPosition?.progress||0)*100)}% · ${escapeHTML(b.readerPosition?.chapter||'No current chapter')}</p><button id="menuOpen">Open Reader</button><button id="menuCustomize">Customize Book</button><label>Move to Library<select id="moveLibrary">${activeLibraries().map(l=>`<option value="${escapeHTML(l.id)}" ${l.id===b.libraryId?'selected':''}>${escapeHTML(l.name)} (${activeBooks(l.id).length}/16)</option>`).join('')}</select></label><button id="menuMove">Move book</button><button id="menuUnstack">Unstack</button><button id="menuTrash">Move to Recently Deleted</button>`;$('#bookMenu').showModal();$('#menuOpen').onclick=()=>{$('#bookMenu').close();openBook(id)};$('#menuCustomize').onclick=()=>{$('#bookMenu').close();openCustomize(id)};$('#menuMove').onclick=async()=>{try{const destination=$('#moveLibrary').value;if(destination!==b.libraryId)await saveArchive(ArchiveModel.move({...archive,books},id,destination));$('#bookMenu').close()}catch(e){serious(e)}};$('#menuUnstack').onclick=async()=>{try{await updateBook(id,b=>({...b,stackId:null,stackOrder:null,stackSchemaVersion:1,stackMode:'separate'}));render();$('#bookMenu').close()}catch(e){serious(e)}};$('#menuTrash').onclick=()=>trashBook(id)}
async function trashBook(id){if(!confirm('Move this book and its entire workspace to Recently Deleted? You can restore it later.'))return;try{await updateBook(id,b=>({...b,deletedAt:Date.now(),stackId:null}));document.querySelectorAll('dialog[open]').forEach(d=>d.close());backToLibrary();message('Moved to Recently Deleted.')}catch(e){serious(e)}}
$('#workspaceActionsMenu').onclick=()=>manageBook(activeBookId);
$('#delete').onclick=()=>trashBook(selected.id);
// Always enter Reader. Switching views afterward preserves both mounted panels.
openBook=function(id){$('#bookPreview').hidden=true;const b=books.find(b=>b.id===id&&!b.deletedAt);if(!b)return;activeBookId=id;currentLibraryId=b.libraryId;workspaceTab='reader';Reader.bookId=null;Board.edit=false;$('#library').hidden=true;$('#workspace').hidden=false;Reader.relinkCardId=null;renderWorkspace();setRoute();$('#workspaceTitle').focus();scrollTo({top:0});};
renderWorkspace=function(){const b=books.find(b=>b.id===activeBookId);if(!b)return backToLibrary();$('#workspaceTitle').textContent=b.title;$('#workspaceAuthor').textContent=b.author+(b.finished?' · Finished':'');$('#attachEPUB').textContent=b.file?'Replace EPUB':'Attach EPUB';if(Board.bookId!==b.id||!$('#boardCanvas'))Board.open(b);else Board.refresh();Reader.open(b);setWorkspaceTab(workspaceTab)};
setWorkspaceTab=function(tab){if(tab==='split'&&matchMedia('(max-width:700px)').matches)tab='reader';workspaceTab=tab;$('#workspacePanels').classList.toggle('split',tab==='split');$('#readerPanel').hidden=tab==='board';$('#boardPanel').hidden=tab==='reader';for(const [id,value] of [['readerTab','reader'],['boardTab','board'],['splitTab','split']]){const b=$('#'+id);b.setAttribute('aria-selected',String(tab===value));b.tabIndex=tab===value?0:-1;}$('#workspacePanels').style.setProperty('--split',getSetting('splitRatio',55)+'%');if(activeBookId)setRoute();requestAnimationFrame(()=>{if(Board.bookId)Board.draw()})};
$('#splitTab').onclick=()=>setWorkspaceTab('split');
$('.workspace-tabs').addEventListener('keydown',e=>{if(!e.target.matches('[role=tab]')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();e.stopImmediatePropagation();const tabs=matchMedia('(max-width:700px)').matches?['reader','board']:['reader','split','board'];let index=tabs.indexOf(workspaceTab);index=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;setWorkspaceTab(tabs[index]);$('#'+tabs[index]+'Tab').focus()},true);
$('#workspacePanels').addEventListener('pointerdown',e=>{if(workspaceTab!=='split'||e.target!==e.currentTarget)return;const el=e.currentTarget;el.setPointerCapture(e.pointerId);const move=e=>{const rect=el.getBoundingClientRect(),ratio=Math.min(75,Math.max(30,(e.clientX-rect.left)/rect.width*100));el.style.setProperty('--split',ratio+'%');el.dataset.ratio=ratio};const up=async()=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',up);try{await setting('splitRatio',Number(el.dataset.ratio)||55)}catch(e){serious(e)}};el.addEventListener('pointermove',move);el.addEventListener('pointerup',up)});
restoreRoute=function(){const match=location.hash.match(/^#book\/([^/]+)/);if(match){try{const id=decodeURIComponent(match[1]);if(books.some(b=>b.id===id&&!b.deletedAt))return openBook(id)}catch{}}backToLibrary(false)};
importFile=async function(file,targetId=null){try{if(!targetId)ensureCapacity();document.body.classList.add('busy');const attachment=await parseEPUB(file);if(targetId){await updateBook(targetId,b=>{const next=attachToBook(b,attachment);return b.file?ArchiveModel.replaceEPUB(next,{file:attachment.file,cover:attachment.cover,packagePath:attachment.packagePath}):next});Reader.bookId=null;renderWorkspace();message('EPUB saved. Existing designs, notes and cards preserved.')}else{const b={...newBookRecord(attachment.title,attachment.author),...attachment,libraryId:currentLibraryId,order:Date.now()};await persist(b);books.push(b);archive.books=books;render();message('Imported. Customize metadata from the book menu.')}}catch(e){serious(e)}finally{document.body.classList.remove('busy');$('#file').value=''}};
$('#createForm').onsubmit=async e=>{e.preventDefault();try{ensureCapacity();const f=e.currentTarget,title=f.elements.title.value.trim();if(!title)throw new Error('A title is required.');creationDraft={...newBookRecord(title,f.elements.author.value.trim()),libraryId:currentLibraryId};const file=f.elements.epub.files[0];if(file){const a=await parseEPUB(file);creationDraft=attachToBook(creationDraft,a)}$('#createDialog').close();openCustomize(creationDraft.id)}catch(e){creationDraft=null;serious(e)}};
const originalOpenCustomize=openCustomize;
openCustomize=function(id){if(creationDraft?.id===id){selected=creationDraft;const f=$('#editForm');f.elements.title.value=selected.title;f.elements.author.value=selected.author;setAppearanceForm(appearanceOf(selected));$('#detailBody').innerHTML='<h2>Design your new book</h2><p>Nothing is saved until you choose Save.</p>';$('#detail').showModal()}else originalOpenCustomize(id);designDraft=structuredClone(selected.design||{});$('#delete').hidden=!!creationDraft;$('#designLibrary').innerHTML=activeLibraries().map(l=>`<option value="${l.id}" ${l.id===selected.libraryId?'selected':''}>${escapeHTML(l.name)} (${activeBooks(l.id).length}/16)</option>`).join('');setupStudio();updatePreview()};
$('#detail').addEventListener('close',()=>{if(!$('#detail').open){creationDraft=null;designDraft=null}});
$('#editForm').onsubmit=async e=>{e.preventDefault();try{const f=e.currentTarget,title=f.elements.title.value.trim(),destination=$('#designLibrary').value;if(!title)throw new Error('A title is required.');if(creationDraft||destination!==selected.libraryId)ensureCapacity(destination);const changes={title,author:f.elements.author.value.trim()||'Unknown author',appearance:appearanceFromForm(),color:f.elements.color.value,type:f.elements.type.value,design:structuredClone(designDraft||{}),libraryId:destination};if(creationDraft){const b={...creationDraft,...changes};await persist(b);books.push(b)}else await updateBook(selected.id,b=>({...b,...changes,stackId:destination!==b.libraryId?null:b.stackId,appearanceDefaults:b.appearanceDefaults||defaultAppearance(b)}));$('#detail').close();archive.books=books;currentLibraryId=destination;render();if(activeBookId)renderWorkspace();message('Design saved.')}catch(e){serious(e)}};
// Studio augments, rather than discards, existing shape/typography controls.
function setupStudio(){if(!$('#studioControls'))$('.appearance-settings').insertAdjacentHTML('beforeend',`<div id="studioControls"><h3>Artwork</h3><label>Image<input id="spineArt" type="file" accept="image/png,image/jpeg,image/webp"></label><label>Background mode<select id="artMode"><option value="color">Color only</option><option value="image">Image only</option><option value="both">Image + typography</option></select></label><label>Fit<select id="artFit"><option>cover</option><option>contain</option></select></label><label>Zoom<input id="artZoom" type="range" min=".5" max="3" step=".05"></label><label>Image X %<input id="artX" type="range" min="0" max="100"></label><label>Image Y %<input id="artY" type="range" min="0" max="100"></label><h3>Independent type elements</h3><div id="textDesignControls"></div></div>`);
  const d=designDraft;$('#artMode').value=d.mode||'color';$('#artFit').value=d.fit||'cover';$('#artZoom').value=d.zoom||1;$('#artX').value=d.x??50;$('#artY').value=d.y??50;$('#spineArt').value='';
  $('#textDesignControls').innerHTML=['title','author'].map(key=>{const t=d[key]||{};return `<fieldset><legend>${key}</legend><label><input type="checkbox" data-text="${key}" data-prop="show" ${t.show===false?'':'checked'}> Show ${key}</label><label>Font<select data-text="${key}" data-prop="font"><option value="">Default</option><option value="Georgia">Georgia</option><option value="Arial">Arial</option>${archive.fonts.map(f=>`<option value="font-${f.id}">${escapeHTML(f.name)}</option>`).join('')}</select></label>${[['size',10,80,t.size||22],['weight',100,900,t.weight||500],['spacing',-2,12,t.spacing||0],['rotation',-180,180,t.rotation??(appearanceOf(selected).orientation==='horizontal'?0:key==='title'?-90:90)],['x',0,100,t.x??(key==='title'?40:80)],['y',0,100,t.y??50]].map(([prop,min,max,value])=>`<label>${prop}<input type="number" min="${min}" max="${max}" value="${value}" data-text="${key}" data-prop="${prop}"></label>`).join('')}<label>Text color<input type="color" data-text="${key}" data-prop="color" value="${t.color||'#111111'}"></label></fieldset>`}).join('');
  for(const input of $('#textDesignControls').querySelectorAll('select'))input.value=d[input.dataset.text]?.font||'';
  $('#studioControls').oninput=()=>{designDraft={...designDraft,mode:$('#artMode').value,fit:$('#artFit').value,zoom:+$('#artZoom').value,x:+$('#artX').value,y:+$('#artY').value};for(const input of $('#textDesignControls').querySelectorAll('[data-text]')){const key=input.dataset.text,prop=input.dataset.prop;designDraft[key]={...designDraft[key],[prop]:input.type==='checkbox'?input.checked:input.type==='number'?Number(input.value):input.value}}updatePreview()};
  $('#spineArt').onchange=async e=>{try{const file=e.target.files[0];if(file){await validateImage(file);designDraft.artwork=file;designDraft.mode='both';$('#artMode').value='both';updatePreview()}}catch(e){serious(e)}};
}
const legacyPreview=updatePreview;
updatePreview=function(){legacyPreview();if(!selected)return;const preview=$('#appearancePreview .book');if(preview)applyDesign(preview,{...selected,design:designDraft||selected.design});};
function applyDesign(el,book){const d=book.design;if(!d)return;const art=d.mode!=='color'&&d.artwork;if(art){el.style.backgroundImage=`url("${assetURL(d.artwork)}")`;el.style.backgroundRepeat='no-repeat';el.style.backgroundSize=(d.zoom&&d.zoom!==1?Math.round(d.zoom*100)+'% auto':d.fit||'cover');el.style.backgroundPosition=`${d.x??50}% ${d.y??50}%`}
  for(const key of ['title','author']){const node=el.querySelector('.spine-'+key),t=d[key];if(!node)continue;if(d.mode==='image'||t?.show===false){node.style.display='none';continue}if(!t)continue;Object.assign(node.style,{position:'absolute',writingMode:'horizontal-tb',left:(clamp(t.x,0,100,50))+'%',top:(clamp(t.y,0,100,50))+'%',bottom:'auto',right:'auto',transform:`translate(-50%,-50%) rotate(${clamp(t.rotation,-180,180,0)}deg)`,fontFamily:/^font-[\w-]+$/.test(t.font)?'"'+t.font+'"':['Georgia','Arial'].includes(t.font)?t.font:'',fontSize:clamp(t.size,10,80,22)+'px',fontWeight:clamp(t.weight,100,900,500),letterSpacing:clamp(t.spacing,-2,12,0)+'px',color:/^#[0-9a-f]{6}$/i.test(t.color)?t.color:'#111111',maxHeight:'none',maxWidth:'none',whiteSpace:'nowrap'})}
  if(el.closest('#appearancePreview'))for(const key of ['title','author']){const node=el.querySelector('.spine-'+key);if(!node||!designDraft?.[key])continue;node.style.cursor='move';node.onpointerdown=e=>{e.preventDefault();node.setPointerCapture(e.pointerId);const rect=el.getBoundingClientRect(),start={...designDraft[key]},x=e.clientX,y=e.clientY;node.onpointermove=e=>{designDraft[key]={...start,x:clamp((start.x??50)+(e.clientX-x)/rect.width*100,0,100,50),y:clamp((start.y??50)+(e.clientY-y)/rect.height*100,0,100,50)};node.style.left=designDraft[key].x+'%';node.style.top=designDraft[key].y+'%'};node.onpointerup=()=>{node.onpointermove=null;setupStudio();updatePreview()}}}
}
const composeRender=render;render=function(){composeRender();$('#books').querySelectorAll('[data-id]').forEach(el=>{const b=books.find(b=>b.id===el.dataset.id);applyDesign(el,b)});};
const legacyReset=$('#resetAppearance').onclick;$('#resetAppearance').onclick=()=>{designDraft={};setupStudio();legacyReset()};
const loadedFonts=new Map();
async function loadFonts(){for(const font of archive.fonts){if(loadedFonts.has(font.id))continue;try{const face=new FontFace('font-'+font.id,await font.file.arrayBuffer());await face.load();document.fonts.add(face);loadedFonts.set(font.id,face)}catch{message('A stored font could not be loaded: '+font.name,true)}}}
async function exportArchive(){try{archive.books=books;const zip=new JSZip();let count=0;async function encode(value){if(value instanceof Blob){const path='assets/'+(++count);zip.file(path,await value.arrayBuffer());return {$asset:path,type:value.type,name:value.name||null}}if(Array.isArray(value))return Promise.all(value.map(encode));if(value&&typeof value==='object'){const result={};for(const [key,item] of Object.entries(value))result[key]=await encode(item);return result}return value}
  zip.file('archive.json',JSON.stringify({version:2,data:await encode(archive)},null,2));const blob=await zip.generateAsync({type:'blob',compression:'DEFLATE'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='archive-of-me-backup.zip';link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);await setting('lastBackup',Date.now());message('Complete archive backup exported.');
}catch(e){serious(e)}}
async function decodeBackup(file){if(file.size>250*1024*1024)throw new Error('Backup exceeds the 250 MB prototype import limit.');const zip=await JSZip.loadAsync(file);if(Object.keys(zip.files).length>20000)throw new Error('Too many backup entries.');const manifest=zip.file('archive.json');if(!manifest)throw new Error('This is not a complete Archive of Me version-2 backup. Older library-only ZIPs can supply EPUBs by re-importing them.');const raw=await manifest.async('string');if(raw.length>20*1024*1024)throw new Error('Backup metadata is too large.');const parsed=JSON.parse(raw);if(parsed.version!==2)throw new Error('Unsupported backup version.');let total=0;
  async function decode(value){if(value&&typeof value==='object'&&value.$asset){if(!/^assets\/\d+$/.test(value.$asset)||!zip.file(value.$asset))throw new Error('Missing backup asset.');const bytes=await zip.file(value.$asset).async('uint8array');total+=bytes.length;if(total>500*1024*1024)throw new Error('Uncompressed backup exceeds 500 MB.');return value.name?new File([bytes],String(value.name),{type:value.type||''}):new Blob([bytes],{type:value.type||''})}if(Array.isArray(value))return Promise.all(value.map(decode));if(value&&typeof value==='object'){const out={};for(const [k,v] of Object.entries(value)){if(['__proto__','constructor','prototype'].includes(k))throw new Error('Invalid backup key.');out[k]=await decode(v)}return out}return value}
  const data=ArchiveModel.validate(await decode(parsed.data));for(const b of data.books){if(b.file)await parseEPUB(b.file);if(b.design?.artwork)await validateImage(b.design.artwork);for(const c of b.board?.cards||[])if(c.image)await validateImage(c.image)}for(const f of data.fonts){if(!(f.file instanceof Blob))throw new Error('Missing font file.');await new FontFace('validate-'+f.id,await f.file.arrayBuffer()).load()}return data;
}
async function restoreArchive(file,mode){try{const incoming=await decodeBackup(file);let next;if(mode==='replace'){if(!confirm('Replace the ENTIRE local archive with this validated backup? Export your current archive first. This replaces all Libraries, books, fonts and settings.'))return;next=incoming}else{next={};let conflicts=0;for(const store of ArchiveDB.stores)conflicts+=incoming[store].filter(x=>archive[store].some(y=>y.id===x.id)).length;let replace=false;if(conflicts){const choice=prompt(conflicts+' matching IDs found. Type KEEP to preserve current versions, or INCOMING to replace matching IDs. Cancel aborts restore.','KEEP');if(choice===null)return;if(!['KEEP','INCOMING'].includes(choice.trim().toUpperCase()))throw new Error('Restore canceled: choose KEEP or INCOMING explicitly.');replace=choice.trim().toUpperCase()==='INCOMING';}for(const store of ArchiveDB.stores){const map=new Map(archive[store].map(x=>[x.id,x]));for(const record of incoming[store])if(!map.has(record.id)||replace)map.set(record.id,record);next[store]=[...map.values()]}ArchiveModel.validate(next)}await saveArchive(next,mode==='replace');Reader.bookId=null;Board.bookId=null;for(const face of loadedFonts.values())document.fonts.delete(face);loadedFonts.clear();await loadFonts();backToLibrary();$('#settingsDialog').close();message('Archive restored atomically.')}catch(e){serious(e)}}
function openSettings(section='application'){
  const active=activeLibraries(),archived=archive.libraries.filter(l=>l.archived),trash=books.filter(b=>b.deletedAt);
  $('#settingsBody').innerHTML=`<h2>Settings</h2><p>Browser-local archive · export before changing devices or clearing data.</p><section><h3>Libraries</h3><div id="libraryManagement">${[...active,...archived].map(l=>`<div class="library-management" data-manage-library="${l.id}"><label>Name<input data-lib-name value="${escapeHTML(l.name)}"></label><label>Background<input type="color" data-lib-background value="${l.background}"></label><label>Shelf line<input type="color" data-lib-line value="${l.line}"></label><button data-lib-save>Save</button><button data-lib-up>↑</button><button data-lib-down>↓</button><button data-lib-archive>${l.archived?'Restore Library':'Archive Library'}</button><span>${activeBooks(l.id).length}/16${l.archived?' · Archived':''}</span></div>`).join('')}</div></section><section><h3>Shared Font Library</h3><label>Import font (TTF, OTF, WOFF, WOFF2)<input id="fontUpload" type="file" accept=".ttf,.otf,.woff,.woff2"></label><ul>${archive.fonts.map(f=>`<li>${escapeHTML(f.name)}</li>`).join('')||'<li>No custom fonts yet.</li>'}</ul></section><section><h3>Storage & backup</h3><p id="storageOverview">Calculating…</p><button id="settingsExport">Export complete ZIP</button><label>Restore mode<select id="restoreMode"><option value="merge">Merge (preserve current archive)</option><option value="replace">Replace entire archive</option></select></label><label>Restore backup ZIP<input id="restoreFile" type="file" accept=".zip"></label><label>Remind me to back up<select id="backupReminder"><option value="7">Every 7 days</option><option value="14">Every 14 days</option><option value="30">Every 30 days</option><option value="0">Off</option></select></label><p>Last backup: ${getSetting('lastBackup',null)?new Date(getSetting('lastBackup')).toLocaleString():'Never'}</p></section><section><h3>Recently Deleted</h3><p>Kept indefinitely until you explicitly delete permanently.</p>${trash.map(b=>`<div class="trash-book"><strong>${escapeHTML(b.title)}</strong><select data-restore-target="${b.id}" aria-label="Restore destination"><option value="">Choose active Library</option>${active.map(l=>`<option value="${l.id}" ${l.id===b.libraryId?'selected':''}>${escapeHTML(l.name)} (${activeBooks(l.id).length}/16)</option>`).join('')}</select><button data-restore-book="${b.id}">Restore</button><button data-purge-book="${b.id}">Delete permanently</button></div>`).join('')||'<p>Nothing in Recently Deleted.</p>'}</section>`;
  if(section==='libraries')$('#settingsBody h2').textContent='Library settings';$('#settingsBody').querySelectorAll('section').forEach((el,i)=>el.hidden=section==='libraries'?i!==0:i===0);$('#settingsDialog').showModal();$('#backupReminder').value=getSetting('backupReminder',14);$('#backupReminder').onchange=async e=>{try{await setting('backupReminder',+e.target.value);message('Reminder preference saved.')}catch(e){serious(e)}};
  navigator.storage?.estimate().then(est=>{if($('#storageOverview'))$('#storageOverview').textContent=`${(est.usage/1024/1024).toFixed(1)} MB used · ${(est.quota/1024/1024).toFixed(0)} MB available quota · ${books.length} books, ${archive.fonts.length} fonts`});
  $('#settingsExport').onclick=exportArchive;$('#restoreFile').onchange=e=>{if(e.target.files[0])restoreArchive(e.target.files[0],$('#restoreMode').value)};
  $('#fontUpload').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(!/\.(ttf|otf|woff2?)$/i.test(file.name)||file.size>15*1024*1024)throw new Error('Choose a supported font under 15 MB.');const id=crypto.randomUUID(),face=new FontFace('font-'+id,await file.arrayBuffer());await face.load();await saveArchive({...archive,books,fonts:[...archive.fonts,{id,name:file.name,file}]});document.fonts.add(face);loadedFonts.set(id,face);$('#settingsDialog').close();openSettings();message('Font imported.')}catch(e){serious(e)}};
  $('#libraryManagement').onclick=async e=>{const row=e.target.closest('[data-manage-library]');if(!row)return;const id=row.dataset.manageLibrary;try{let libraries=structuredClone(archive.libraries),l=libraries.find(l=>l.id===id);if(e.target.closest('[data-lib-save]')){const name=row.querySelector('[data-lib-name]').value.trim();if(!name)throw new Error('Library name is required.');l.name=name;l.background=row.querySelector('[data-lib-background]').value;l.line=row.querySelector('[data-lib-line]').value}else if(e.target.closest('[data-lib-archive]'))l.archived=!l.archived;else if(e.target.closest('[data-lib-up],[data-lib-down]')){const sorted=libraries.sort((a,b)=>a.order-b.order),i=sorted.findIndex(l=>l.id===id),to=Math.min(sorted.length-1,Math.max(0,i+(e.target.closest('[data-lib-up]')?-1:1)));sorted.splice(to,0,sorted.splice(i,1)[0]);sorted.forEach((l,i)=>l.order=i)}else return;await saveArchive({...archive,books,libraries});$('#settingsDialog').close();openSettings(section)}catch(e){serious(e)}};
  $('#settingsBody').querySelectorAll('[data-restore-book]').forEach(el=>el.onclick=async()=>{try{const id=el.dataset.restoreBook,destination=$('#settingsBody').querySelector(`[data-restore-target="${CSS.escape(id)}"]`).value;ensureCapacity(destination);await updateBook(id,b=>({...b,deletedAt:null,libraryId:destination,order:Date.now()}));render();$('#settingsDialog').close();openSettings()}catch(e){serious(e)}});
  $('#settingsBody').querySelectorAll('[data-purge-book]').forEach(el=>el.onclick=async()=>{if(!confirm('PERMANENTLY DELETE this book, EPUB, annotations, artwork and Story Board? This cannot be undone.'))return;try{await transaction('readwrite',store=>store.delete(el.dataset.purgeBook));books=books.filter(b=>b.id!==el.dataset.purgeBook);archive.books=books;$('#settingsDialog').close();openSettings();message('Permanently deleted.')}catch(e){serious(e)}});
}
